@page "/category/{Slug}"

<PageTitle>@GetCategoryName() Recipes</PageTitle>

<h1>@GetCategoryEmoji() @GetCategoryName() Recipes</h1>
<p>Browse our collection of @GetCategoryName().ToLower() recipes.</p>

<div class="list-group">
    @foreach (var recipe in GetRecipes())
    {
        <a href="/recipe/@recipe.Id" class="list-group-item list-group-item-action">
            <div class="d-flex w-100 justify-content-between">
                <h5 class="mb-1">@recipe.Title</h5>
                <small>@recipe.PrepTime</small>
            </div>
            <p class="mb-1">@recipe.Summary</p>
        </a>
    }
</div>

<div class="mt-3">
    <a href="/" class="btn btn-secondary">← Back to Categories</a>
</div>

@code {
    [Parameter]
    public string Slug { get; set; } = "";

    private string GetCategoryName() => Slug switch
    {
        "appetizers" => "Appetizers",
        "main-courses" => "Main Courses",
        "desserts" => "Desserts",
        "beverages" => "Beverages",
        "baking" => "Baking",
        "vegetarian" => "Vegetarian",
        _ => "Recipes"
    };

    private string GetCategoryEmoji() => Slug switch
    {
        "appetizers" => "🥗",
        "main-courses" => "🍝",
        "desserts" => "🍰",
        "beverages" => "🥤",
        "baking" => "🍞",
        "vegetarian" => "🥬",
        _ => "🍽️"
    };

    private List<RecipeListItem> GetRecipes() => Slug switch
    {
        "appetizers" => new()
        {
            new("bruschetta", "Classic Bruschetta", "Toasted bread with fresh tomatoes and basil", "15 min"),
            new("spinach-dip", "Creamy Spinach Dip", "Warm spinach and artichoke dip", "25 min"),
            new("stuffed-mushrooms", "Stuffed Mushrooms", "Mushroom caps filled with herbed cream cheese", "30 min")
        },
        "main-courses" => new()
        {
            new("spaghetti-carbonara", "Spaghetti Carbonara", "Classic Italian pasta with egg and pancetta", "30 min"),
            new("grilled-salmon", "Grilled Salmon", "Herb-crusted salmon with lemon butter", "25 min"),
            new("chicken-stir-fry", "Chicken Stir Fry", "Quick weeknight stir fry with vegetables", "20 min")
        },
        "desserts" => new()
        {
            new("chocolate-cake", "Chocolate Lava Cake", "Rich molten chocolate cake", "45 min"),
            new("tiramisu", "Classic Tiramisu", "Italian coffee-flavored layered dessert", "40 min"),
            new("apple-pie", "Apple Pie", "Traditional apple pie with flaky crust", "60 min")
        },
        "beverages" => new()
        {
            new("mango-smoothie", "Mango Smoothie", "Tropical mango and yogurt smoothie", "5 min"),
            new("iced-coffee", "Iced Vanilla Coffee", "Cold brew with vanilla syrup", "10 min")
        },
        "baking" => new()
        {
            new("sourdough", "Sourdough Bread", "Artisan sourdough with crispy crust", "24 hrs"),
            new("croissants", "Butter Croissants", "Flaky French croissants", "4 hrs")
        },
        "vegetarian" => new()
        {
            new("veggie-curry", "Thai Vegetable Curry", "Coconut milk curry with seasonal vegetables", "35 min"),
            new("mushroom-risotto", "Mushroom Risotto", "Creamy arborio rice with wild mushrooms", "40 min")
        },
        _ => new()
    };

    private record RecipeListItem(string Id, string Title, string Summary, string PrepTime);
}

@rendermode InteractiveServer

<div class="star-rating">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= CurrentRating ? "filled" : "")"
              @onclick="() => SetRating(star)"
              @onmouseover="() => HoverRating = star"
              @onmouseout="() => HoverRating = 0"
              style="cursor: pointer; font-size: 1.5rem;">
            @(star <= (HoverRating > 0 ? HoverRating : CurrentRating) ? "★" : "☆")
        </span>
    }
    @if (CurrentRating > 0)
    {
        <span class="ms-2 text-muted">(@CurrentRating / 5)</span>
    }
    @if (ShowConfirmation)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }
</div>

@code {
    [Parameter]
    public string RecipeId { get; set; } = "";

    private int CurrentRating { get; set; }
    private int HoverRating { get; set; }
    private bool ShowConfirmation { get; set; }

    private void SetRating(int rating)
    {
        CurrentRating = rating;
        ShowConfirmation = true;
    }
}

@page "/submit"
@rendermode InteractiveServer

<PageTitle>Submit a Recipe</PageTitle>

<h1>📝 Submit Your Recipe</h1>
<p>Share your favorite recipe with the community!</p>

@if (IsSubmitted)
{
    <div class="alert alert-success">
        <h4>🎉 Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@Model.Title</strong>" with the community.</p>
        <a href="/" class="btn btn-primary">Back to Home</a>
        <button class="btn btn-outline-secondary ms-2" @onclick="ResetForm">Submit Another</button>
    </div>
}
else
{
    <EditForm Model="@Model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="Model.Title" placeholder="e.g., Grandma's Chocolate Chip Cookies" />
            <ValidationMessage For="() => Model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="Model.Category">
                <option value="">-- Select a category --</option>
                <option value="appetizers">Appetizers</option>
                <option value="main-courses">Main Courses</option>
                <option value="desserts">Desserts</option>
                <option value="beverages">Beverages</option>
                <option value="baking">Baking</option>
                <option value="vegetarian">Vegetarian</option>
            </InputSelect>
            <ValidationMessage For="() => Model.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="Model.Ingredients"
                           placeholder="Enter each ingredient on a new line, e.g.:&#10;2 cups flour&#10;1 cup sugar&#10;3 eggs" />
            <ValidationMessage For="() => Model.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Preparation Steps</label>
            <InputTextArea id="steps" class="form-control" rows="6" @bind-Value="Model.Steps"
                           placeholder="Enter each step on a new line, e.g.:&#10;Preheat oven to 350°F&#10;Mix dry ingredients&#10;Add wet ingredients and stir" />
            <ValidationMessage For="() => Model.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
        <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    private RecipeFormModel Model { get; set; } = new();
    private bool IsSubmitted { get; set; }

    private void HandleSubmit()
    {
        IsSubmitted = true;
    }

    private void ResetForm()
    {
        Model = new();
        IsSubmitted = false;
    }
}

using System.ComponentModel.DataAnnotations;

namespace RecipeSharing.Components.Pages;

public class RecipeFormModel
{
    [Required(ErrorMessage = "Please enter a recipe title.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be between 3 and 100 characters.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = "";

    [Required(ErrorMessage = "Please list the ingredients.")]
    [MinLength(5, ErrorMessage = "Please provide more detail for ingredients.")]
    public string Ingredients { get; set; } = "";

    [Required(ErrorMessage = "Please describe the preparation steps.")]
    [MinLength(10, ErrorMessage = "Please provide more detail for the steps.")]
    public string Steps { get; set; } = "";
}

