@rendermode InteractiveServer

<div class="star-rating">
    <span class="me-2">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= CurrentRating ? "filled" : "")"
              @onclick="() => SetRating(star)"
              @onmouseover="() => HoverRating = star"
              @onmouseout="() => HoverRating = 0"
              style="cursor: pointer; font-size: 1.5rem;">
            @(star <= (HoverRating > 0 ? HoverRating : CurrentRating) ? "★" : "☆")
        </span>
    }
    @if (CurrentRating > 0)
    {
        <span class="ms-2 text-muted">(@CurrentRating / 5)</span>
    }
    @if (ShowConfirmation)
    {
        <span class="ms-2 text-success">✓ Thanks for rating!</span>
    }
</div>

@code {
    [Parameter]
    public string RecipeId { get; set; } = "";

    private int CurrentRating { get; set; }
    private int HoverRating { get; set; }
    private bool ShowConfirmation { get; set; }

    private void SetRating(int rating)
    {
        CurrentRating = rating;
        ShowConfirmation = true;
    }
}

